import { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import { collection, addDoc, serverTimestamp, query, onSnapshot, orderBy } from "firebase/firestore";

export default function GroupChat({ group, currentUser, onClose }) {

    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");
    const listRef = useRef(null);

    useEffect(() => {
        const messagesRef = collection(db, `groups/${group.id}/messages`);
        const q = query(messagesRef, orderBy("createdAt", "asc"));
        return onSnapshot(q, snap => {
            setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));

            // scroll automático
            setTimeout(() => {
                if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
            }, 100);
        });
    }, [group.id]);

    const send = async () => {
        if (!text.trim()) return;

        await addDoc(messagesRef, {
            text,
            from: currentUser.uid,
            createdAt: serverTimestamp()
        });

        setText("");
    };

    return (
        <div className="whatsapp-container">

            {/* ← COLUNA ESQUERDA (voltar) */}
            <div className="sidebar">
                <div className="sidebar-header">
                    <button onClick={onClose} style={{ background: "transparent", border: "none", color: "white" }}>
                        ← Voltar
                    </button>
                </div>
            </div>

            {/* → ÁREA DO CHAT */}
            <div className="chat-area">

                <div className="chat-header">
                    {group.name}
                </div>

                <div className="chat-box" ref={listRef}>
                    {messages.map(m => (
                        <div key={m.id} className={`msg ${m.from === currentUser.uid ? "me" : "other"}`}>
                            {m.text}
                        </div>
                    ))}
                </div>

                <div className="chat-input">
                    <input
                        value={text}
                        onChange={e => setText(e.target.value)}
                        placeholder="Mensagem..."
                    />
                    <button onClick={send}>Enviar</button>
                </div>

            </div>
        </div>
    );
}
